import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Naive 3D convolution CUDA code
conv3d_naive_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv3d_naive_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int B, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_k, int H_k, int W_k,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int dilationD, int dilationH, int dilationW,
    int outD, int outH, int outW,
    bool bias_flag
){
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total_threads = B * C_out * outD * outH * outW;
    if (index >= total_threads) return;

    // Decompose linear index into (b, c_out, d_out, h_out, w_out)
    int w_out_i = index % outW;
    int tmp = index / outW;
    int h_out_i = tmp % outH;
    tmp /= outH;
    int d_out_i = tmp % outD;
    tmp /= outD;
    int c_out_i = tmp % C_out;
    int b_i = tmp / C_out;

    float value = 0.0f;
    // Convolution loops
    for (int c_in_i = 0; c_in_i < C_in; c_in_i++){
        for (int kd = 0; kd < D_k; kd++){
            for (int kh = 0; kh < H_k; kh++){
                for (int kw = 0; kw < W_k; kw++){
                    int in_d = d_out_i * strideD - padD + kd * dilationD;
                    int in_h = h_out_i * strideH - padH + kh * dilationH;
                    int in_w = w_out_i * strideW - padW + kw * dilationW;

                    if (in_d >= 0 && in_d < D_in &&
                        in_h >= 0 && in_h < H_in &&
                        in_w >= 0 && in_w < W_in) {
                        float inp_val = input[b_i * (C_in * D_in * H_in * W_in) +
                                              c_in_i * (D_in * H_in * W_in) +
                                              in_d * (H_in * W_in) +
                                              in_h * W_in + in_w];
                        float w_val = weight[c_out_i * (C_in * D_k * H_k * W_k) +
                                             c_in_i * (D_k * H_k * W_k) +
                                             kd * (H_k * W_k) +
                                             kh * W_k + kw];
                        value += inp_val * w_val;
                    }
                }
            }
        }
    }
    if (bias_flag) {
        value += bias[c_out_i];
    }
    output[b_i * (C_out * outD * outH * outW) +
           c_out_i * (outD * outH * outW) +
           d_out_i * (outH * outW) +
           h_out_i * outW + w_out_i] = value;
}

torch::Tensor conv3d_naive_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int dilationD, int dilationH, int dilationW,
    bool bias_flag
){
    auto B = input.size(0);
    auto C_in = input.size(1);
    auto D_in = input.size(2);
    auto H_in = input.size(3);
    auto W_in = input.size(4);

    auto C_out = weight.size(0);
    auto D_k = weight.size(2);
    auto H_k = weight.size(3);
    auto W_k = weight.size(4);

    int outD = (D_in + 2 * padD - dilationD * (D_k - 1) - 1) / strideD + 1;
    int outH = (H_in + 2 * padH - dilationH * (H_k - 1) - 1) / strideH + 1;
    int outW = (W_in + 2 * padW - dilationW * (W_k - 1) - 1) / strideW + 1;

    auto options = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    auto output = torch::zeros({B, C_out, outD, outH, outW}, options);

    int total_threads = B * C_out * outD * outH * outW;
    int blockSize = 256;
    int gridSize = (total_threads + blockSize - 1) / blockSize;

    conv3d_naive_kernel<<<gridSize, blockSize>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_flag ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        B, C_in, D_in, H_in, W_in,
        C_out, D_k, H_k, W_k,
        strideD, strideH, strideW,
        padD, padH, padW,
        dilationD, dilationH, dilationW,
        outD, outH, outW,
        bias_flag
    );
    return output;
}
""".strip()

conv3d_naive_cpp_source = r"""
torch::Tensor conv3d_naive_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int dilationD, int dilationH, int dilationW,
    bool bias_flag
);
""".strip()

# Build the CUDA extension inline
conv3d_naive = load_inline(
    name="conv3d_naive",
    cpp_sources=conv3d_naive_cpp_source,
    cuda_sources=conv3d_naive_source,
    functions=["conv3d_naive_forward"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Custom 3D convolution using a naive CUDA kernel for forward pass.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0),
                 dilation: tuple = (1, 1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        if groups != 1:
            raise NotImplementedError("Groups > 1 not implemented in this naive kernel.")

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.bias_flag = bias

        # Initialize weights (C_out, C_in, D_k, H_k, W_k)
        self.weight = nn.Parameter(
            torch.randn(out_channels, in_channels, kernel_size[0], kernel_size[1], kernel_size[2])
        )
        if bias:
            self.bias = nn.Parameter(torch.zeros(out_channels))
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv3d_naive.conv3d_naive_forward(
            x,
            self.weight,
            torch.zeros(1, device=x.device) if self.bias is None else self.bias,
            self.stride[0], self.stride[1], self.stride[2],
            self.padding[0], self.padding[1], self.padding[2],
            self.dilation[0], self.dilation[1], self.dilation[2],
            self.bias_flag
        )
